\label{e-frame} 
Let $\mathcal{C}_h$ and $\mathcal{C}_v$ be two classes of unimodal frames. An {\em expanding domain frame} is a pair $(\mathfrak{F},f)$, where $\mathfrak{F}=(W,\prec_h)\in\mathcal{C}_h$ is the {\em horizontal frame} and $f:W\to\mathcal{C}_v$ is a function assigning to each $x\in W$ a {\em vertical frame} $f(x)=(W^x,\prec_v^x)\in\mathcal{C}_v$, in such a way that whenever $x \prec_h y$ for $x,y\in W$, the frame $f(x)$ is a subframe of $f(y)$; that is,
    \begin{enumerate}
    \item[(i)] $W^x \subseteq W^y$, and
    \item[(ii)] $u \prec_v^x w$ iff $u \prec_v^y w$ for all $u,w\in W^x$.
    \end{enumerate}
We denote the class of all such frames by $(\mathcal{C}_h \times \mathcal{C}_v)^{\sf e}$. 

A {\em valuation} on $(\mathfrak F,f)$ is a family $V=(V^x)_{x \in W}$ such that, for each $x \in W$,  $V^x$ is a valuation on the frame $f(x)=(W^x,\prec_v^x)$. A triple $\mathfrak{M} = (\mathfrak{F}, f, V)$, consisting of an expanding domain frame with a valuation is an {\em expanding domain model.}

\label{EquiEmbe&Expan} 
Let $\mathcal C_h$ and $\mathcal C_v$ be two classes of transitive frames.
\begin{enumerate}
    \item \label{1EquiEmbe&Expan} If a formula is satisfiable in an expanding domain frame $(\mathcal C_h \times \mathcal C_v )^{\sf e}$, then it is satisfiable in a $(\mathcal C_h \rtimes \mathcal C_v )^{\sf e}$-frame.
    \item \label{2EquiEmbe&Expan} If a formula is satisfiable in a $(\mathcal C_h \rtimes \mathcal C_v )^{\sf e}$-frame whose horizontal component is a tree, then it is satisfiable in an expanding domain frame in $(\mathcal C_h \times \mathcal C_v )^{\sf e}$.
\end{enumerate}

\label{FrameDefs}\label{ModelDefs}
A {\em forward-confluent frame} is a triple $\mathcal F =(W,\prec_h,\prec_v)$, where $\prec_h$ and $\prec_v$ are binary relations on $W$ satisfying the properties of {\em Left Commutativity} (LC) and {\em Church-Rosser} (CR): 
\begin{itemize}
\item[(LC)] if $x \prec_v x' \prec_h y'$, then there exists $y\in W$ such that $x \prec_h y \prec_v y'$;
\item[(CR)] if $x' \succ_v x \prec_h y$, then there exists $y'\in W$ such that $x' \prec_h y' \succ_v y$.
\end{itemize}
Given classes of frames $\mathcal C_h$ and $\mathcal C_v$, the class of all forward-confluent frames where $(W,\prec_h ) \in \mathcal C_h$ and $(W,\prec_v ) \in \mathcal C_v$ is denoted by $\mathcal C_h \rtimes \mathcal C_v$. 

A {\em forward-confluent model} $\mathcal{M} = (W, \prec_h, \prec_v, \left\llbracket \cdot \right\rrbracket)$ is a forward-confluent frame equipped
with a valuation $\left\llbracket \cdot \right\rrbracket : \mathrm{Prop} \to \mathcal{P}(W)$.

\label{propLC}
Let $\mathcal F = (W, \prec_h, \prec_v)$ be an arbitrary bi-relational frame.
Using $\models$ to denote first-order validity, we have:
\begin{enumerate}
    \item $\mathcal F \models \mbox{(LC)} $ if and only if $\mathcal F \vDash \Diamond_v \Diamond_h p \to \Diamond_h \Diamond_v p$, and
    \item $\mathcal F \models \mbox{(CR)}$ if and only if $ \mathcal F \vDash \Diamond_h \Box_v p \to \Box_v \Diamond_h p$.
\end{enumerate}

\label{ExtoFCModel}
Let $\mathcal C_h$ and $\mathcal C_v$ be classes of Kripke frames closed under disjoint unions.
If a formula is satisfied in a $(\mathcal C_h\times \mathcal C_v)^{\sf e}$-model, then it is satisfied in a $\mathcal C_h\rtimes \mathcal C_v$-model.

Given an expanding domain model $\mathfrak{M} = (\mathfrak{F}, f, V)$ where $\mathfrak{F} = (W, \prec_h )$, $f(x) = (W^x, \prec_v^x)$ for each $x \in W$ and $V=(V^x)_{x \in W}$, we define a  model $\overline{\mathfrak{M}} := (\overline{W}, \prec_h, \prec_v, \left\llbracket \cdot \right\rrbracket)$, where
\begin{itemize}
    \item $\overline{W}:= \{(x,u) \mid x \in W, u \in W^x\}$;
    \item $(x,u) \prec_h (y, w)$ iff $x \prec_h y$ and $u = w$;
    \item $(x, u) \prec_v (y,w)$ iff $x = y$ and $u \prec_v^x w$;
    \item $\left\llbracket p \right\rrbracket := \{(x, u) \mid u \in V^x(p)\}$ for any $p \in \mathrm{Prop}$.
\end{itemize}
We can show that $\mathfrak{M}, (x, u) \Vdash \varphi$ if and only if $\overline{\mathfrak{M}}, (x, u) \Vdash \varphi$ by an easy induction on $\varphi \in \mathcal L_{hv}$, whose details are left to the reader. It only remains to verify that the confluence conditions are met. 
\begin{description}[wide, labelwidth=!, labelindent=5pt, itemsep=0pt]
\item[(LC)] Suppose $(x,u) \prec_v (x',u') \prec_h (y',w')$. Then $x=x'$, $u \prec_v^x u'$, $u'=w'$, and $x'\prec_h y'$. Consider $(y',u)$. Since $x=x'$ and $x' \prec_h y'$, we have $x \prec_h y'$, and therefore $(x,u) \prec_h (y',u)$. Moreover, since $u \prec_v^x u'$ and $x \prec_h y'$, the subframe condition implies $u \prec_v^{y'} u'$. As $u'=w'$, we conclude $(y',u) \prec_v (y',w')$.

\item[(CR)] Suppose $(x',u') \succ_v (x,u) \prec_h (y,w)$. Then $x=x'$, $u \prec_v^x u'$, $u=w$, and $x \prec_h y$. Consider $(y,u')$. Since $x \prec_h y$ and $x=x'$, we obtain $(x',u') \prec_h (y,u')$. Furthermore, from $u \prec_v^x u'$ and the subframe condition we get $u \prec_v^y u'$, which yields $(y,w) \prec_v (y,u')$ since $u=w$. 
\end{description}

It is readily verified that $(\overline W,\prec_h)$ and $(\overline W,\prec_v)$ are isomorphic to disjoint unions of frames from $\mathcal C_h$ and $\mathcal C_v$, respectively, so indeed the new model belongs to $\mathcal C_h\rtimes \mathcal C_v$.

\label{defExpandingCommutator}
Let $\mathsf{L}_h$ and $\mathsf{L}_v$ be normal unimodal logics.
The \emph{expanding commutator} $[{\sf L}_h, {\sf L}_v]^{\sf e}$ is the least logic over $\mathcal L_{hv}$ containing all horizontal instances of formulas of $\mathsf{L}_h$, all vertical instances of formulas of $\mathsf{L}_v$, and the expanding product axiom schemes
\begin{description}
\item[] $\Diamond_v \Diamond_h p \to \Diamond_h \Diamond_v p$ \hfill \textit{(Left commutativity)} 
\item[] $\Diamond_v \Box_h p \to \Box_h \Diamond_v p$ \hfill \textit{(Church--Rosser)}.
\end{description}

\label{RemarkK4xK4}
Let $\mathsf{L}_h, \mathsf{L}_v$ be unimodal logics, let $\varphi, \psi, \varphi_1, \dots, \varphi_n \in \mathcal L_{hv}$. The usual reasoning is available in the expanding commutator $[{\sf L}_h, {\sf L}_v]^{\sf e}$ for both modalities given $\alpha \in \{h,v\}$.
    \begin{enumerate}
    \item \label{1RemarkK4xK4}$\vdash \Box_\alpha \varphi_1 \wedge ... \wedge \Box_\alpha \varphi_n \leftrightarrow \Box_\alpha (\varphi_1 \wedge ... \wedge \varphi_n)$.
    \item \label{2RemarkK4xK4} $\vdash \Diamond_\alpha (\varphi_1 \wedge ... \wedge \varphi_n) \to \Diamond_\alpha \varphi_1 \wedge ... \wedge \Diamond_\alpha \varphi_n$.
    \item \label{3RemarkK4xK4} If $\;\vdash \varphi \to \psi$, then $\;\vdash \Diamond_\alpha \varphi \to \Diamond_\alpha \psi$.
    \end{enumerate}

\label{theorem:IncompletenessUsingLinearity}
Let ${\sf L}_h\supseteq \sf K4.3$ be valid on $\ensuremath{\text{ 


  \textit{\fontfamily{qzc}\selectfont3} 
}^{*}}$ and ${\sf L}_v$ be any logic valid on $\ensuremath{\text{ 


  \textit{\fontfamily{qzc}\selectfont2} 
}^{\Ydown}}$. Then, 
$[{\sf L}_h, {\sf L}_v]^{\sf e}$ is incomplete for $({\sf L}_h \times {\sf L}_v)^{\sf e}$.

In particular, all of $[{\sf Grz.3}, {\sf GL}]^{\sf e}$, $[{\sf K4.3}, {\sf GL}]^{\sf e}$, and $[{\sf K4.3}, {\sf K}]^{\sf e}$ are incomplete.

Consider the formula
\[
\varphi := \Diamond_h p\wedge \Diamond_v\Diamond_h q \to \Diamond_h(p\wedge \Diamond_v \diamonddot_h   q) \vee \Diamond_h(\diamonddot_h p\wedge \Diamond_v    q). 
\]
We claim that $\varphi$ is valid over $(\mathsf{K4.3}\times\mathsf K)^{\sf e}$, whence over $(\mathsf L_h\times\mathsf  L_v)^{\sf e}$.

To see this, fix a $ (\mathsf{K4.3}\times\mathsf K)^{\sf e}$-model $\mathfrak M $   and assume that $ (x,u)\Vdash \Diamond_h p\wedge \Diamond_v\Diamond_h q$.
From the left conjunct, we find some $(y,u)$ with $y \succ_h x$ such that $(y,u)\Vdash p$, while the right conjunct yields $(z,w)\Vdash q$ for $x \prec_h z$ and $u \prec_v^{z} w$. Since the horizontal frame satisfies the $\sf{3}$ axiom and is transitive, we get either $y\prec_h z$ or $z=y \vee z \prec_h y$, corresponding to $\Diamond_h(p\wedge \Diamond_v \diamonddot_h q)$ and $\Diamond_h(\diamonddot_h p\wedge \Diamond_v q)$, respectively.

We now consider the forward-confluent model $\mathcal{M}_1 := (W, \prec_h, \prec_v, V)$ defined by
\begin{itemize}
    \item $W := \{0,1,2\} \times \{0,1\}$;
    \item $(x,y) \prec_h (x',y')$ iff $x\leq x'$ and $y=y'$;
    \item $(x,y) \prec_v (x',y')$ iff $(x,x') \in \{(0,0),(1,2),(2,1), (2,2)\}$ and $y<y'$;
    \item $V(p) := \{(1,0)\}$ and $V(q) := \{(1,1)\}$.  
\end{itemize}

