More concretely, we have that 
\begin{itemize}
    \item $W :=\{0,1,2 \}$;
    \item  $1\preccurlyeq_h 2$ and $i\preccurlyeq_h i$ for $i\in \{0,1,2 \}$;
    \item $0\prec_v 1$ and $0\prec_v 2$;
    \item $V(p) :=\{0,1,2\}$ and  $V(q) := \{1\}$.
\end{itemize}
Using the assumption that $ \ensuremath{\text{ 


  \textit{\fontfamily{qzc}\selectfont2} 
}^{*}}\Vdash \mathsf L_h$ and $\ensuremath{\text{ 


  \textit{\fontfamily{qzc}\selectfont2} 
}^{\Ydown}}\Vdash \mathsf L_v$, it is quite simple to see that $\mathcal{M}_2$ is a $\mathsf L_h\rtimes \mathsf L_v$-model and that $\mathcal{M}_2, 0\not \Vdash \psi$.

Let $\mathsf L_h$, $\mathsf L_v$ be unimodal logics. The \emph{canonical model for $[\mathsf{L}_h,\mathsf{L}_v]^{\sf e}$} is the tuple
\[\mathcal M^{\rm c} := (W^{\rm c},\prec_h^{\rm c},\prec_v^{\rm c}, \left\llbracket \cdot \right\rrbracket ^{\rm c}),\]
where
\begin{itemize}
    \item $W^{\rm c}$ is the set of all maximally consistent sets in $[\mathsf{L}_h,\mathsf{L}_v]^{\sf e}$;
    \item $\prec_\alpha^{\rm c}$ for $\alpha \in \{h,v\}$ is the binary relation on $W^{\rm c}$ defined by $\Phi \prec_\alpha^{\rm c} \Psi$ iff for all $\varphi \in \mathcal L_{hv}$, $\varphi \in \Psi$ implies $\Diamond_\alpha \varphi \in \Phi$;
    \item $\left\llbracket p \right\rrbracket^{\rm c} := \{\Phi \in W^{\rm c} \mid p \in \Phi \}$ for $p \in \mathrm{Prop}$.   
\end{itemize}

\label{Canonicalmodel$[K4,K4]^e$}
Let $\mathsf L_h$, $\mathsf L_v$ be unimodal logics and let $\mathcal M^{\rm c}$ be the canonical model for $[ \mathsf L_h, \mathsf L_v]^{\sf e}$. Then:
\begin{enumerate}
    \item\label{itForConf} $\mathcal M^{\rm c}$ is forward-confluent.
    \item\label{itTrans} For $\alpha\in\{h,v\}$, if $\mathsf L_\alpha$ extends $\sf K4$, then $\prec_\alpha$ is transitive.
    \item\label{TruthLemma} The truth lemma holds for $\mathcal M^{\rm c}$, i.e. for any $\Phi \in W^{\rm c}$ and $\varphi \in \mathcal L_{hv}$, we have $\varphi \in \Phi$ iff $\mathcal M^{\rm c}, \Phi \Vdash \varphi$.
\end{enumerate}

\begin{enumerate}[wide, labelwidth=!, labelindent=0pt, itemsep=5pt]
\item[\ref{itForConf}.] 
    \begin{description}[wide, labelwidth=!, labelindent=5pt, itemsep=0pt]
    \item[(LC)] Assume that $\Phi \prec_v^{\rm c} \Upsilon \prec_h^{\rm c} \Psi$. Let $\Phi^{\Box_h} := \{\varphi \mid \Box_h \varphi \in \Phi\}$ and $\Psi^{\Diamond_v} := \{\Diamond_v \psi \mid \psi \in \Psi\}$. It suffices to show that $\Theta^{-} := \Phi^{\Box_h} \cup \Psi^{\Diamond_v}$ is consistent in $[{\sf L}_h, {\sf L}_v]^{\sf e}$. We can then use Lindenbaum's lemma and Lemma \ref{BoxCanonicalModels} to conclude that there is a maximal consistent extension $\Theta \supseteq \Theta^{-}$ which satisfies $\Phi \prec_h^{\rm c} \Theta \prec_v^{\rm c} \Psi$. 

    Suppose, towards a contradiction, that $\Theta^-$ is inconsistent. Then, there exist finite subsets $\Phi_0\subseteq\Phi$ and $\Psi_0 \subseteq \Psi$ such that $\vdash \bigwedge \Psi_0^{\Diamond_v} \to \neg \bigwedge \Phi_0^{\Box_h}$. By Remark~\ref{RemarkK4xK4}\eqref{2RemarkK4xK4}, we have $\vdash \Diamond_v \bigwedge \Psi_0 \to \neg \bigwedge \Phi_0^{\Box_h}$. Then, applying Remark~\ref{RemarkK4xK4}\eqref{3RemarkK4xK4} we deduce
    \begin{equation}
    \label{EqConfl1}
    \vdash \Diamond_h \Diamond_v \bigwedge \Psi_0 \to \neg \Box_h \bigwedge \Phi_0^{\Box_h}.
    \end{equation}

    On the other hand, since $\Upsilon \prec_h^{\rm c} \Psi$, we clearly have that $\Diamond_h \bigwedge \Psi_0 \in \Upsilon$. Moreover, given that $\Phi \prec_v^{\rm c} \Upsilon$, we get $\Diamond_v \Diamond_h \bigwedge \Psi_0 \in \Phi$. Given that $\Phi$ is a $[{\sf L}_h,{\sf L}_v]^{\sf e}$-maximal consistent set, by the left-commutativity axiom we have that $\Diamond_h \Diamond_v \bigwedge \Psi_0 \in \Phi$. Therefore, from (\ref{EqConfl1}) we obtain $\neg \Box_h \bigwedge \Phi_0^{\Box_h} \in \Phi$, that is, $\Box_h \bigwedge \Phi_0^{\Box_h} \notin \Phi$. This concludes the proof by contradiction using Remark~\ref{RemarkK4xK4}\eqref{1RemarkK4xK4}.

    \item[(CR)] Assume that $\Upsilon \succ_v^{\rm c} \Phi \prec_h^{\rm c} \Theta$. Let $\Upsilon^{\Box_h} := \{\varphi \mid \Box_h \varphi \in \Upsilon\}$ and $\Theta^{\Box_v} := \{\psi \mid \Box_v \psi \in \Theta\}$. It suffices to see that $\Psi^{-} := \Upsilon^{\Box_h} \cup \Theta^{\Box_v}$ is consistent in $[{\sf L}_h, {\sf L}_v]^{\sf e}$.
    By Lindenbaum's lemma we can find a maximal consistent extension $\Psi \supseteq \Psi^{-}$ which satisfies $\Upsilon \prec_h^{\rm c} \Psi \succ_v^{\rm c} \Theta$, guaranteed by Lemma \ref{BoxCanonicalModels}.

    Suppose, towards contradiction, that $\Psi^{-}$ is inconsistent. Then, we have that $\vdash \bigwedge \Upsilon_0^{\Box_h} \to \neg \bigwedge \Theta_0^{\Box_v}$ for some finite subsets $\Upsilon_0\subseteq\Upsilon$ and $\Theta_0\subseteq\Theta$, and by Remark~\ref{RemarkK4xK4}\eqref{3RemarkK4xK4} we can deduce that
    \begin{equation}
    \label{EqConf2}
        \vdash\Diamond_v \bigwedge \Upsilon_0^{\Box_h} \to \neg \Box_v \bigwedge \Theta_0^{\Box_v}. 
    \end{equation}  
    On the other hand, by Remark~\ref{RemarkK4xK4}\eqref{1RemarkK4xK4}, we clearly have $\Box_h \bigwedge \Upsilon_0^{\Box_h} \in \Upsilon$. Since  $\Phi \prec_v^{\rm c} \Upsilon$, we deduce that $\Diamond_v \Box_h \bigwedge \Upsilon_0^{\Box_h} \in \Phi$. Hence, by the Church-Rosser axiom we show that $\Box_h \Diamond_v \bigwedge \Upsilon_0^{\Box_h} \in \Phi$. Now, from $\Phi \prec_h^{\rm c} \Theta$ using Lemma \ref{BoxCanonicalModels} we deduce $\Diamond_v \bigwedge \Upsilon_0^{\Box_h} \in \Theta$. Therefore, we get $\neg \Box_v \bigwedge \Theta_0^{\Box_v} \in \Theta$ by (\ref{EqConf2}), that is, $\Box_v \bigwedge \Theta_0^{\Box_v} \notin \Theta$. This concludes the proof by contradiction using Remark~\ref{RemarkK4xK4}\eqref{1RemarkK4xK4}.
    \end{description}

\item[\ref{itTrans}.] Suppose that $\Phi \prec_\alpha^{\rm c} \Psi \prec_\alpha^{\rm c} \Upsilon$ for $\alpha \in \{h, v\}$, and let $\varphi \in \Upsilon$. Then $\Diamond_\alpha \varphi \in \Psi$, and hence $\Diamond_\alpha \Diamond_\alpha \varphi \in \Phi$. 
By transitivity axiom and this fact that $\Phi$ is closed under derivability, we have $\Diamond_\alpha \varphi \in \Phi$. Thus, $\Phi \prec_\alpha^{\rm c} \Upsilon$. 

\item[\ref{TruthLemma}.] This is standard (see e.g.~\cite{Chagrov1997}) and can be proven by structural induction on $\varphi$, using the witness property~(Lemma~\ref{WitnessCanonicalModel}) for modal cases.\qedhere
\end{enumerate}

\label{defSType}
Let $\Sigma \subseteq \mathcal L_{hv}$ be closed under subformulas and single negations; we write this as $\Sigma\Subset\mathcal L_{hv}$. A {\em $\Sigma$-type} is any $\Phi \subseteq \Sigma$ satisfying the following properties:
\begin{enumerate}
    \item $\neg\varphi\in \Phi$ iff $\varphi\notin \Phi$, for every $\neg\varphi\in \Sigma$, and
    \item $\varphi \wedge \psi \in \Phi$ iff $\varphi, \psi \in \Phi$, for every $\varphi \wedge \psi \in \Sigma$.
\end{enumerate}
The set of all finite $\Sigma$-types is denoted by $\mathrm{T}_\Sigma$.

\label{ts}
Let $\Sigma\Subset\mathcal L_{hv}$, and $\mathfrak{m}$ and $\mathfrak{n}$ be $\Sigma$-quasimoments. 
\begin{enumerate}
    \item Say that $\mathfrak n$ is a {\em successor} of $\mathfrak m$, denoted $\mathfrak m \prec_h^\Sigma \mathfrak n$, if there exists an embedding $e \colon |\mathfrak m| \to |\mathfrak n|$ such that for every $w \in |\mathfrak m|$, we have $\ell^\mathfrak m(w) \prec_h^{\rm \Sigma} \ell^\mathfrak n(e(w))$.
   \item Moreover, we write $\mathfrak m\sqsubseteq^\Sigma\mathfrak n$ if $\mathfrak m$ embeds into $\mathfrak n$ preserving both the root and the labeling, in which case we say that $ \mathfrak m$ is a {\em submoment} of $\mathfrak n$.
\end{enumerate}

\label{thmWQO}
Let $\Sigma\Subset\mathcal L_{hv}$.
The set $\mathbb M_\Sigma$ is well-quasi-ordered by $\sqsubseteq^\Sigma$.

\label{defDefects}
Let $\Sigma\Subset\mathcal L_{hv}$. A {\em potential defect} $\delta$ of a $\Sigma$-quasimoment $\mathfrak m$ is a pair $\delta = (w, \Diamond_\alpha \varphi)$ such that $\Diamond_\alpha \varphi \in \ell^{\mathfrak m}(w)$, where $\alpha \in \{h,v\}$. 
\begin{itemize}
    \item A potential defect $\delta$ is called a {\em horizontal defect} if $\alpha = h$. We say that a $\Sigma$-quasimoment $\mathfrak n$ {\em realizes} the horizontal defect $(w, \Diamond_h \varphi)$ if $\mathfrak m \prec_h^\Sigma\mathfrak n$ via an embedding $e : |\mathfrak{m}| \to |\mathfrak{n}|$ with $\varphi \in \ell^{\mathfrak n}(e(w))$.
    \item A potential defect $\delta$ is called a {\em vertical defect} if $\alpha = v$ and there is no $u \succ_v^{\mathfrak m} w$ such that $\varphi \in \ell^{\mathfrak m}(u)$.
\end{itemize}

To prove this, we construct a sequence $(\mathfrak{m}_i)_{i \in \mathbb{N}}$ of $\Sigma$-quasimoments and show that it eventually stabilizes at a $\Sigma$-moment $\mathfrak{m}$ such that $\mathfrak{m} \rightharpoonup \Phi$.

Consider the sequence $(\mathfrak{m}_i)_{i \in \mathbb{N}}$ defined recursively as:
\begin{itemize}
    \item $\mathfrak{m}_0 := (\{w\}, \prec_v^0, \ell^0)$, where $\prec_v^0 := \emptyset$ and $\ell^0(w) := \Phi \cap \Sigma$.
    \item Given $\mathfrak{m}_i = (|\mathfrak{m}_i|, \prec_v^i, \ell^i)$, the $\Sigma$-quasimoment $\mathfrak{m}_{i+1}$ is obtained by extending $\mathfrak{m}_i$ as follows: for every vertical defect $(u, \Diamond_v \varphi)$ of $\mathfrak{m}_i$ with $\ell^i(u) = \Psi \cap \Sigma$, introduce a fresh node $u'$ such that $u \prec_v^{i+1} u'$, and define $\ell^{i+1}(u') := \Psi' \cap \Sigma$ 
    where $\Psi' \in W^{\mathrm c}$ is chosen so that $\Psi \prec_v^{\mathrm c} \Psi'$ and $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$, as given by the witness property (Lemma~\ref{WitnessCanonicalModel}).

    In this case, we say that $u$ is a \emph{defect node of $\mathfrak{m}_i$}, and $u'$ \emph{realizes the defect} $(u, \Diamond_v \varphi)$ in $\mathfrak{m}_{i+1}$, or simply $u'$ \emph{realizes a defect at} $u$. 
\end{itemize}

We first see that the sequence is well-defined.

\begin{claim}
\label{Claim1}
$\mathfrak{m}_i$ is a $\Sigma$-quasimoment for any $i \in \mathbb{N}$.
\end{claim}

\begin{proofof}{Claim \ref{Claim1}}
We proceed by induction on $i \in \mathbb{N}$. The base case is immediate. For the inductive step, it suffices to verify that the homomorphism condition is preserved at the fresh nodes added in $\mathfrak{m}_{i+1}$, since it holds elsewhere by the inductive hypothesis.

Let $u' \in |\mathfrak{m}_{i+1}|$ be a fresh node realizing a defect at $(u, \Diamond_v \varphi)$ of $\mathfrak{m}_{i}$, with $\ell^{i+1}(u) = \Psi \cap \Sigma$ and $\ell^{i+1}(u') = \Psi' \cap \Sigma$, where $\Psi \prec_v^{\rm c} \Psi'$ and $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Let $\Diamond_v \psi \in \Sigma$. 
\begin{enumerate}
    \item If $\psi \in \Psi' \cap \Sigma$, then $\Diamond_v \psi \in \Psi$ by $\Psi \prec_v^{\rm c} \Psi'$. Hence, $\Diamond_v \psi \in \Psi \cap \Sigma$.
    \item If $\Diamond_v \psi \in \Psi' \cap \Sigma$, then $\Diamond_v \Diamond_v \psi \in \Psi$ by $\Psi \prec_v^{\rm c} \Psi'$. Since $\Psi$ is maximal consistent, transitivity yields $\Diamond_v \psi \in \Psi$. Thus, $\Diamond_v \psi \in \Psi \cap \Sigma$. \qedhere
\end{enumerate}
\end{proofof}

We next show that the sequence of $\Sigma$-quasimoments stabilizes, i.e. there exists $k \in \mathbb{N}$ such that $\mathfrak{m}_k = \mathfrak{m}_j$ for all $j \geq k$. The $\Sigma$-quasimoment $\mathfrak{m}_k$ is called the {\em limit} of $(\mathfrak{m}_i)_{i \in \mathbb{N}}$.

\begin{claim}
\label{Claim2} The sequence $(\mathfrak{m}_i)_{i \in \mathbb{N}}$ stabilizes.
\end{claim}

\begin{proofof}{Claim \ref{Claim2}}
Let $\mathrm{def}_i(u)$ denote the set of formulas $\Diamond_v \varphi$ such that $(u, \Diamond_v \varphi)$ is a vertical defect of $\mathfrak{m}_i$. It suffices to show that 
\begin{equation}
\label{eqCl2}
\mathrm{def}_{i+1}(u') \subsetneq \mathrm{def}_i(u)
\end{equation} 
for every $u' \in |\mathfrak{m}_{i+1}|$ realizing a defect node $u \in |\mathfrak{m}_i|$. Indeed, $\mathfrak{m}_i$ only extends properly to $\mathfrak{m}_{i+1}$ in order to realize existing defects. Since $\Sigma$ is finite, there are only finitely many defects in $\mathfrak{m}_0$. By \eqref{eqCl2}, whenever a fresh node is added to realize a defect node, its set of defects is strictly contained in that of the node it realizes. It follows that along any branch of the construction, the sets of defects form a strictly decreasing chain with respect to inclusion, so the construction must stabilize.

To show the inclusion in (\ref{eqCl2}), consider $\Diamond_v \psi \in \mathrm{def}_{i+1}(u')$ such that $u'$ is a fresh node realizing the defect $(u, \Diamond_v \varphi)$ in $\mathfrak{m}_i$. Let $\ell^{i+1}(u) = \Psi \cap \Sigma$ and $\ell^{i+1}(u') = \Psi' \cap \Sigma$, where $\Psi \prec_v^{\rm c} \Psi'$ and $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Since $\Diamond_v \psi \in \Psi'$ and $\Psi \prec_v^{\rm c} \Psi'$, it follows that $\Diamond_v \Diamond_v \psi \in \Psi$. As $\Psi$ is a maximal consistent set, transitivity yields $\Diamond_v \psi \in \Psi$, and hence $\Diamond_v \psi \in \Psi \cap \Sigma$. Moreover, it is straightforward to verify by induction on $i \in \mathbb{N}$ that defect nodes have no successors. Thus, $(u, \Diamond_v \psi)$ is, in particular, a vertical defect of $\mathfrak{m}_i$, showing that $\mathrm{def}_{i+1}(u') \subseteq \mathrm{def}_i(u)$. Finally, the inclusion is strict: indeed, $\Diamond_v \varphi \in \mathrm{def}_i(u)$ but by construction $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Hence, $\Diamond_v \varphi \notin \Psi'$, so we conclude that $\Diamond_v \varphi \notin \mathrm{def}_{i+1}(u')$.
\end{proofof}

Let $\mathfrak{m}$ denote the limit of $(\mathfrak{m}_i)_{i \in \mathbb{N}}$. We conclude that $\mathfrak{m}$ is the desired $\Sigma$-moment simulating $\Phi \in W^{\rm c}$.
\begin{claim}
\label{Claim3}
$\mathfrak{m}$ is a $\Sigma$-moment satisfying $\mathfrak{m}\rightharpoonup \Phi$.
\end{claim}

\begin{proofof}{Claim \ref{Claim3}}
To see that $\mathfrak{m}$ is a $\Sigma$-moment, it suffices to show that for every $u \in |\mathfrak{m}_i|$ with $\Diamond_v \varphi \in \ell^{i}(u)$, there exists $j \geq i$ and $u' \in \mathfrak{m}_j$ such that $u \prec_v^{j} u'$ and $\varphi \in \ell^j(u')$. The result follows by an easy induction on $i \in \mathbb{N}$, whose details are left to the reader.

Thus, we conclude $\mathfrak{m} \rightharpoonup \Phi$ via the simulation $\sigma : |\mathfrak{m}| \to W^{\mathrm c}$ defined by setting $\sigma(u) := \Psi$ for every $u \in |\mathfrak{m}|$ with $\ell^{\mathfrak{m}}(u) = \Psi \cap \Sigma$.
\end{proofof}
\qedhere

We proceed by induction on $i \in \mathbb{N}$. The base case is immediate. For the inductive step, it suffices to verify that the homomorphism condition is preserved at the fresh nodes added in $\mathfrak{m}_{i+1}$, since it holds elsewhere by the inductive hypothesis.

Let $u' \in |\mathfrak{m}_{i+1}|$ be a fresh node realizing a defect at $(u, \Diamond_v \varphi)$ of $\mathfrak{m}_{i}$, with $\ell^{i+1}(u) = \Psi \cap \Sigma$ and $\ell^{i+1}(u') = \Psi' \cap \Sigma$, where $\Psi \prec_v^{\rm c} \Psi'$ and $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Let $\Diamond_v \psi \in \Sigma$. 
\begin{enumerate}
    \item If $\psi \in \Psi' \cap \Sigma$, then $\Diamond_v \psi \in \Psi$ by $\Psi \prec_v^{\rm c} \Psi'$. Hence, $\Diamond_v \psi \in \Psi \cap \Sigma$.
    \item If $\Diamond_v \psi \in \Psi' \cap \Sigma$, then $\Diamond_v \Diamond_v \psi \in \Psi$ by $\Psi \prec_v^{\rm c} \Psi'$. Since $\Psi$ is maximal consistent, transitivity yields $\Diamond_v \psi \in \Psi$. Thus, $\Diamond_v \psi \in \Psi \cap \Sigma$. \qedhere
\end{enumerate}

Let $\mathrm{def}_i(u)$ denote the set of formulas $\Diamond_v \varphi$ such that $(u, \Diamond_v \varphi)$ is a vertical defect of $\mathfrak{m}_i$. It suffices to show that 
\begin{equation}
\label{eqCl2}
\mathrm{def}_{i+1}(u') \subsetneq \mathrm{def}_i(u)
\end{equation} 
for every $u' \in |\mathfrak{m}_{i+1}|$ realizing a defect node $u \in |\mathfrak{m}_i|$. Indeed, $\mathfrak{m}_i$ only extends properly to $\mathfrak{m}_{i+1}$ in order to realize existing defects. Since $\Sigma$ is finite, there are only finitely many defects in $\mathfrak{m}_0$. By \eqref{eqCl2}, whenever a fresh node is added to realize a defect node, its set of defects is strictly contained in that of the node it realizes. It follows that along any branch of the construction, the sets of defects form a strictly decreasing chain with respect to inclusion, so the construction must stabilize.

To show the inclusion in (\ref{eqCl2}), consider $\Diamond_v \psi \in \mathrm{def}_{i+1}(u')$ such that $u'$ is a fresh node realizing the defect $(u, \Diamond_v \varphi)$ in $\mathfrak{m}_i$. Let $\ell^{i+1}(u) = \Psi \cap \Sigma$ and $\ell^{i+1}(u') = \Psi' \cap \Sigma$, where $\Psi \prec_v^{\rm c} \Psi'$ and $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Since $\Diamond_v \psi \in \Psi'$ and $\Psi \prec_v^{\rm c} \Psi'$, it follows that $\Diamond_v \Diamond_v \psi \in \Psi$. As $\Psi$ is a maximal consistent set, transitivity yields $\Diamond_v \psi \in \Psi$, and hence $\Diamond_v \psi \in \Psi \cap \Sigma$. Moreover, it is straightforward to verify by induction on $i \in \mathbb{N}$ that defect nodes have no successors. Thus, $(u, \Diamond_v \psi)$ is, in particular, a vertical defect of $\mathfrak{m}_i$, showing that $\mathrm{def}_{i+1}(u') \subseteq \mathrm{def}_i(u)$. Finally, the inclusion is strict: indeed, $\Diamond_v \varphi \in \mathrm{def}_i(u)$ but by construction $\varphi \wedge \neg \Diamond_v \varphi \in \Psi'$. Hence, $\Diamond_v \varphi \notin \Psi'$, so we conclude that $\Diamond_v \varphi \notin \mathrm{def}_{i+1}(u')$.

\label{QuasiMomToMom}
Let $\Sigma\Subset\mathcal L_{hv}$. If $\mathfrak m$ is a $\Sigma$-quasimoment and $\mathfrak m \rightharpoonup \Phi$ for some $\Phi \in W^{\rm c}$, then there exists a $\Sigma$-moment $ex(\mathfrak m)$ such that 
\[\mathfrak m \sqsubseteq^\Sigma ex(\mathfrak m) \quad\text{and}\quad ex(\mathfrak m) \rightharpoonup \Phi.\]

Let $\delta = (w, \Diamond_h \varphi)$ be a horizontal defect of $\mathfrak{m}$ and let $\sigma : |\mathfrak{m}| \to W^{\rm c}$ be the simulation such that $\mathfrak{m} \rightharpoonup \Phi$. We define recursively a sequence $\{(\mathfrak{m}_i, e_i, \sigma_i)\}_{i \in \mathbb{N}}$ such that, for each $i \in \mathbb{N}$, $\mathfrak{m}_i$ is a $\Sigma$-quasimoment, $e_i$ is a partial embedding, and $\sigma_i : |\mathfrak{m}_i| \to W^{\rm c}$ is a simulation satisfying
\[
\sigma(u) \prec_h^{\rm c} \sigma_i(e_i(u)) \quad \text{for all } u \in \mathrm{Dom}(e_i)
\]
where $\mathrm{Dom}(e_i)$ denotes the domain of the partial embedding $e_i$.
\begin{enumerate}[label=$\bullet$, wide, labelwidth=!, labelindent=5pt, itemsep=0pt]
    \item We first define $\mathfrak{m}_0 := (\{w'\}, \prec_v^0, \ell^0)$, where $\prec_v^0 := \emptyset$ and $\ell^0(w') := \Psi \cap \Sigma$ for some $\Psi \in W^{\rm c}$ such that $\Psi \succ_h^{\rm c} \sigma(w)$, obtained by the witness Lemma~\ref{WitnessCanonicalModel} from the fact that $\Diamond_h \varphi \in \ell^{\mathfrak{m}}(w) = \sigma(w) \cap \Sigma$. Define $e_0(w) := w'$ and $\sigma_0(w') := \Psi$.
    \item Given $(\mathfrak{m}_i, e_i, \sigma_i)$, we construct $(\mathfrak{m}_{i+1}, e_{i+1}, \sigma_{i+1})$ by extending $\mathfrak{m}_i$, $e_i$, and $\sigma_i$ as follows:

    For each $v \in |\mathfrak{m}| \setminus \mathrm{Dom}(e_i)$ such that either $v$ is an immediate $\prec_v^{\mathfrak m}$-predecessor or an immediate $\prec_v^{\mathfrak m}$-successor of some $u\in\mathrm{Dom}(e_i)$, that is,
    \[
    v \prec_v^{\mathfrak m} u
    \quad\text{and there is no }w \neq u, v \text{ with }
    v \prec_v^{\mathfrak m} w \prec_v^{\mathfrak m} u
    \]
    or
    \[
    u \prec_v^{\mathfrak m} v
    \quad\text{and there is no }w \neq u, v\text{ with }
    u \prec_v^{\mathfrak m} w \prec_v^{\mathfrak m} v,
    \]
we add a fresh node $v'$ and extend $e_i$ by setting $e_{i+1}(v):=v'$. The position of $v'$ in $\mathfrak{m}_{i+1}$ is determined by:
    \begin{enumerate}
    \item[(i)] $v' \prec_v^{{i+1}} e_i(u)$ if $v \prec_v^{\mathfrak{m}} u$;
    \item[(ii)] $v' \succ_v^{{i+1}} e_i(u)$ if $v \succ_v^{\mathfrak{m}} u$.
    \end{enumerate}

    Using the properties (LC) and (CR) of the canonical model, we define the label and simulation for $v'$ by setting $\ell^{{i+1}}(v') := \Upsilon \cap \Sigma$ and $\sigma_{i+1}(v') := \Upsilon$, where $\Upsilon \in W^{\rm c}$ satisfies one of the following conditions:
    \begin{enumerate}
    \item[(i)] $\sigma(v) \prec_h^{\rm c} \Upsilon \prec_v^{\rm c} \sigma_i(e_i(u))$ by the property (LC) if $v \prec_v^{\mathfrak{m}} u$ given that $\sigma(v) \prec_v^{\rm c} \sigma(u) \prec_h^{\rm c} \sigma_i(e_i(u))$;
    \item[(ii)] $\sigma(v) \prec_h^{\rm c} \Upsilon \succ_v^{\rm c} \sigma_i(e_i(u))$ by the property (CR) if $v \succ_v^{\mathfrak{m}} u$ given that $\sigma(v) \succ_v^{\rm c} \sigma(u) \prec_h^{\rm c} \sigma_i(e_i(u))$.
    \end{enumerate}
\end{enumerate}

