First, we show that the construction is well-defined.

\begin{claim}\label{Claim1itMomWitLater}
The sequence $\{(\mathfrak{m}_i, e_i, \sigma_i)\}_{i \in \mathbb{N}}$ is well-defined.
\end{claim}

\begin{proofof}{Claim \ref{Claim1itMomWitLater}}
More precisely, we show for every $i \in \mathbb{N}$ that
\begin{enumerate}[label=(\alph*)]
    \item\label{C4a}  $\mathrm{Dom}(e_i) \subseteq |\mathfrak{m}|$ equipped with the relation $\prec_v^{\mathfrak{m}}$ restricted to it forms a tree;
    \item\label{C4b}  $e_i : \mathrm{Dom}(e_i) \to |\mathfrak{m}_i|$ is a $\prec_v$-isomorphism such that $\mathrm{Im}(e_i) = |\mathfrak{m}_i|$, where $\mathrm{Im}(e_i)$ denotes the image of $e_i$;
    \item\label{C4c}  $\mathfrak{m}_i$ is a $\Sigma$-quasimoment;
    \item\label{C4d}  $\sigma_i : |\mathfrak{m}_i| \to W^{\rm c}$ is a simulation satisfying $\sigma(u) \prec_h^{\rm c} \sigma_i(e_i(u))$ for every $u \in \mathrm{Dom}(e_i)$.
\end{enumerate}
The proof proceeds by induction on $i \in \mathbb{N}$. The base case is immediate from the construction. For the inductive step, assume that $(\mathfrak{m}_i, e_i, \sigma_i)$ satisfies \ref{C4a}--\ref{C4d}, and consider the extension to $(\mathfrak{m}_{i+1}, e_{i+1}, \sigma_{i+1})$ as defined in the sequence. We provide details for the first three properties, while the verification of \ref{C4d} follows directly from the definition of the recursive construction and is left to the reader.

\begin{enumerate}[wide, labelwidth=!, labelindent=5pt, itemsep=0pt]
    \item[\ref{C4a}] By the inductive hypothesis, $\mathrm{Dom}(e_i)$ is a tree. The map $e_{i+1}$ is defined to extend $e_i$ with nodes $v \in |\mathfrak{m}| \setminus \mathrm{Dom}(e_i)$ which are immediate $\prec_v^\mathfrak{m}$-predecessors or $\prec_v^\mathfrak{m}$-successors of some $u \in \mathrm{Dom}(e_i)$, together with the edge witnessing this relation. If $v \succ_v^\mathfrak{m} u$, it is straightforward that the extension is still a tree. Otherwise, if $v \prec_v^\mathfrak{m} u$, since $v \notin \mathrm{Dom}(e_i)$ but $u \in \mathrm{Dom}(e_i)$, we deduce that $u$ is the root of the tree $\mathrm{Dom}(e_i)$. Therefore, we have the extension is also a tree for this case. 

    \item[\ref{C4b}] By construction, every new node $v'$ of $\mathfrak{m}_{i+1}$ arises from a unique $v \in |\mathfrak{m}| \setminus \mathrm{Dom}(e_i)$ which is immediate adjacent (in the $\prec_v$-tree structure) to some $u \in \mathrm{Dom}(e_i)$. This element $v$ is added to the domain of $e_{i+1}$ and mapped to $v'$ via $e_{i+1}(v) := v'$, so that $\mathrm{Im}(e_{i+1}) = |\mathfrak{m}_{i+1}|$. Since $e_i$ is a $\prec_v$-isomorphism by the inductive hypothesis and the construction introduces fresh nodes exactly corresponding to previously unmapped elements while respecting adjacency in the tree structure, it follows that $e_{i+1}$ is again bijective. Moreover, the extension is defined so as to preserve the $\prec_v$-relation, and therefore $e_{i+1}$ is a $\prec_v$-isomorphism.

    \item[\ref{C4c}] By \ref{C4a}, $\mathrm{Dom}(e_{i+1})$ is a tree, and by \ref{C4b} so is $(|\mathfrak{m}_{i+1}|, \prec_v^{i+1})$. It remains to verify that the labelling satisfies the homomorphism condition: this follows from the inductive hypothesis together with the definition of the labels of the newly added nodes and the transitivity properties of maximal consistent sets. The details are routine and left to the reader. \qedhere
\end{enumerate}
\end{proofof}

Next, we show that the sequence stabilizes, meaning that it is eventually constant at some element, which we call its {\em limit}.

\begin{claim}\label{Claim3itMomWitLater}
The sequence $\{(\mathfrak{m}_i, e_i, \sigma_i)\}_{i \in \mathbb{N}}$ stabilizes.
\end{claim}

\begin{proofof}{Claim \ref{Claim3itMomWitLater}}
Since the construction properly extends by adding fresh nodes corresponding to nodes in $\mathfrak{m}$ that are not in the domain of the corresponding embedding, it suffices to show that there exists $k \in \mathbb{N}$ such that $\mathrm{Dom}(e_k) = |\mathfrak{m}|$.

To this end, observe that $\mathrm{Dom}(e_i) \subseteq \mathrm{Dom}(e_{i+1})$ for all $i \in \mathbb{N}$ by a straightforward induction on $i \in \mathbb{N}$. Moreover, whenever $\mathrm{Dom}(e_i) \subsetneq |\mathfrak{m}|$, the construction adds at least one new element, so that 
$\mathrm{Dom}(e_i) \subsetneq \mathrm{Dom}(e_{i+1})$. Therefore, since $|\mathfrak{m}|$ is finite, there exists $k \in \mathbb{N}$ such that $\mathrm{Dom}(e_k) = |\mathfrak{m}|$, and the sequence stabilizes. \qedhere
\end{proofof}

Let $(\hat{\mathfrak{m}}, \hat{e}, \hat{\sigma})$ denote the limit of the sequence $\{(\mathfrak{m}_i, e_i, \sigma_i)\}_{i \in \mathbb{N}}$. We show that this limit is already a successor realizing the horizontal defect $\delta$, and that it simulates a maximal consistent set that is a horizontal successor of the one simulated by $\mathfrak{m}$.

\begin{claim}\label{Claim2itMomWitLater}
\begin{enumerate} 
    \item\label{C2succR} $\hat{\mathfrak{m}}$ is a successor of $\mathfrak{m}$ realizing $\delta$.
    \item\label{C2ssim} $\hat{\mathfrak{m}} \rightharpoonup \Phi'$ for some $\Phi' \succ_h^{\rm c} \Phi$.
\end{enumerate}
\end{claim}

\begin{proofof}{Claim \ref{Claim2itMomWitLater}}
\begin{enumerate}[wide, labelwidth=!, labelindent=5pt, itemsep=0pt] 
    \item[\ref{C2succR}.] It suffices to show that $\mathfrak{m} ,\prec_h^\Sigma, \hat{\mathfrak{m}}$ via the embedding $\hat{e}$. Once this is established, we obtain that $\varphi \in \ell^{\hat{\mathfrak{m}}}(\hat{e}(w))$, since $\varphi \in \ell^{i}(e_i(w))$ for every $i \in \mathbb{N}$. The latter fact follows by a straightforward induction on $i$, whose details are left to the reader.

    As observed in Claim \ref{Claim3itMomWitLater}, we have $\mathrm{Dom}(\hat{e}) = |\mathfrak{m}|$, so $\hat{e} : |\mathfrak{m}| \to |\hat{\mathfrak{m}}|$ is a (total) embedding. To verify that $\mathfrak{m} \,\prec_h^\Sigma\, \hat{\mathfrak{m}}$, let $\Diamond_h \psi \in \Sigma$ and suppose that either $\psi \in \ell^{\hat{\mathfrak{m}}}(\hat{e}(u))$ or $\Diamond_h \psi \in \ell^{\hat{\mathfrak{m}}}(\hat{e}(u))$ for some $u \in |\mathfrak{m}|$. Since $\ell^{\hat{\mathfrak{m}}}(\hat{e}(u)) = \hat{\sigma}(\hat{e}(u)) \cap \Sigma$ and $\sigma(u) \prec_h^{\rm c} \hat{\sigma}(\hat{e}(u))$, it follows from the definition of $\prec_h^{\rm c}$ that either $\Diamond_h \psi \in \sigma(u)$ or $\Diamond_h \Diamond_h \psi \in \sigma(u)$. In the latter case, by transitivity and maximal consistency we also obtain $\Diamond_h \psi \in \sigma(u)$. Hence, in both cases we have that $\Diamond_h \psi \in \sigma(u)$, and therefore we conclude $\Diamond_h \psi \in \ell^{\mathfrak{m}}(u)$.

    \item[\ref{C2ssim}.] Let $\Phi' := \hat{\sigma}(r^{\hat{\mathfrak{m}}})$. Since $r^{\hat{\mathfrak{m}}} = \hat{e}(r^{\mathfrak{m}})$, and recalling that $\sigma(r^{\mathfrak{m}}) = \Phi$, it follows from the construction that $\Phi' \succ_h^{\rm c} \Phi$. Hence $\hat{\mathfrak{m}} \rightharpoonup \Phi'$ as required. \qedhere
\end{enumerate}
\end{proofof}

Finally, we extend the $\Sigma$-quasimoment $\hat{\mathfrak{m}}$ to a $\Sigma$-moment $\mathfrak{m}'$ such that $\mathfrak{m}' \rightharpoonup \Phi'$ using Lemma~\ref{QuasiMomToMom}. Moreover, $\hat{e} : |\mathfrak{m}| \to |\mathfrak{m}'|$  witnesses that $\mathfrak m\prec_h^\Sigma \mathfrak m'$, showing that $\mathfrak{m}'$ realizes the horizontal defect $\delta$. This concludes the proof.

More precisely, we show for every $i \in \mathbb{N}$ that
\begin{enumerate}[label=(\alph*)]
    \item\label{C4a}  $\mathrm{Dom}(e_i) \subseteq |\mathfrak{m}|$ equipped with the relation $\prec_v^{\mathfrak{m}}$ restricted to it forms a tree;
    \item\label{C4b}  $e_i : \mathrm{Dom}(e_i) \to |\mathfrak{m}_i|$ is a $\prec_v$-isomorphism such that $\mathrm{Im}(e_i) = |\mathfrak{m}_i|$, where $\mathrm{Im}(e_i)$ denotes the image of $e_i$;
    \item\label{C4c}  $\mathfrak{m}_i$ is a $\Sigma$-quasimoment;
    \item\label{C4d}  $\sigma_i : |\mathfrak{m}_i| \to W^{\rm c}$ is a simulation satisfying $\sigma(u) \prec_h^{\rm c} \sigma_i(e_i(u))$ for every $u \in \mathrm{Dom}(e_i)$.
\end{enumerate}
The proof proceeds by induction on $i \in \mathbb{N}$. The base case is immediate from the construction. For the inductive step, assume that $(\mathfrak{m}_i, e_i, \sigma_i)$ satisfies \ref{C4a}--\ref{C4d}, and consider the extension to $(\mathfrak{m}_{i+1}, e_{i+1}, \sigma_{i+1})$ as defined in the sequence. We provide details for the first three properties, while the verification of \ref{C4d} follows directly from the definition of the recursive construction and is left to the reader.

\begin{enumerate}[wide, labelwidth=!, labelindent=5pt, itemsep=0pt]
    \item[\ref{C4a}] By the inductive hypothesis, $\mathrm{Dom}(e_i)$ is a tree. The map $e_{i+1}$ is defined to extend $e_i$ with nodes $v \in |\mathfrak{m}| \setminus \mathrm{Dom}(e_i)$ which are immediate $\prec_v^\mathfrak{m}$-predecessors or $\prec_v^\mathfrak{m}$-successors of some $u \in \mathrm{Dom}(e_i)$, together with the edge witnessing this relation. If $v \succ_v^\mathfrak{m} u$, it is straightforward that the extension is still a tree. Otherwise, if $v \prec_v^\mathfrak{m} u$, since $v \notin \mathrm{Dom}(e_i)$ but $u \in \mathrm{Dom}(e_i)$, we deduce that $u$ is the root of the tree $\mathrm{Dom}(e_i)$. Therefore, we have the extension is also a tree for this case. 

    \item[\ref{C4b}] By construction, every new node $v'$ of $\mathfrak{m}_{i+1}$ arises from a unique $v \in |\mathfrak{m}| \setminus \mathrm{Dom}(e_i)$ which is immediate adjacent (in the $\prec_v$-tree structure) to some $u \in \mathrm{Dom}(e_i)$. This element $v$ is added to the domain of $e_{i+1}$ and mapped to $v'$ via $e_{i+1}(v) := v'$, so that $\mathrm{Im}(e_{i+1}) = |\mathfrak{m}_{i+1}|$. Since $e_i$ is a $\prec_v$-isomorphism by the inductive hypothesis and the construction introduces fresh nodes exactly corresponding to previously unmapped elements while respecting adjacency in the tree structure, it follows that $e_{i+1}$ is again bijective. Moreover, the extension is defined so as to preserve the $\prec_v$-relation, and therefore $e_{i+1}$ is a $\prec_v$-isomorphism.

    \item[\ref{C4c}] By \ref{C4a}, $\mathrm{Dom}(e_{i+1})$ is a tree, and by \ref{C4b} so is $(|\mathfrak{m}_{i+1}|, \prec_v^{i+1})$. It remains to verify that the labelling satisfies the homomorphism condition: this follows from the inductive hypothesis together with the definition of the labels of the newly added nodes and the transitivity properties of maximal consistent sets. The details are routine and left to the reader. \qedhere
\end{enumerate}

\label{Claim2itMomWitLater}
\begin{enumerate} 
    \item\label{C2succR} $\hat{\mathfrak{m}}$ is a successor of $\mathfrak{m}$ realizing $\delta$.
    \item\label{C2ssim} $\hat{\mathfrak{m}} \rightharpoonup \Phi'$ for some $\Phi' \succ_h^{\rm c} \Phi$.
\end{enumerate}

\label{def:Quasimodel}
Let $\Sigma\Subset\mathcal L_{hv}$. A {\em weak $\Sigma$-quasimodel} is a tuple $\mathfrak Q = (T^\mathfrak{Q} ,\prec_h^\mathfrak{Q} , \mu^\mathfrak{Q})$, where 
\begin{enumerate}
    \item $(T^\mathfrak{Q} ,\prec_h^\mathfrak{Q} ) $ is a transitive, irreflexive tree with root $r^\mathfrak{Q}$ and
    \item $\mu^\mathfrak{Q} \colon T^\mathfrak{Q} \to \mathbb M_\Sigma$ is a homomorphism with respect to $\prec_h$.
\end{enumerate}
We say that $\mathfrak Q$ is a {\em $\Sigma$-quasimodel} if for every $t \in T^\mathfrak{Q}$ and every horizontal defect $\delta$ of the $\Sigma$-moment $\mu^\mathfrak{Q}(t)$, there exists $s\succ_h^\mathfrak{Q} t$ such that $\mu^\mathfrak{Q}(s)$ realizes $\delta$.

\label{lemQuasiToMod}
Let $\Sigma\Subset\mathcal L_{hv}$. If a formula $\varphi \in \Sigma$ is satisfied in a $\Sigma$-quasimodel $\mathfrak Q$, then it is satisfied in a $(\mathsf{K4}\rtimes \mathsf{GL})^{\sf e}$-model $\mathfrak M$.
If moreover $\mathfrak Q$ is finite, then $\mathfrak M$ can be taken to be a $(\mathsf{GL}\rtimes \mathsf{GL})^{\sf e}$-model.

\label{lemExistsQuasiK4}
Let $\Sigma\Subset\mathcal L_{hv}$ and let $\mathcal M^{\rm c}$ be the canonical model of an expanding commutator of the form $[\mathsf L_h,\mathsf{GL}]^{\sf e}$, where $\mathsf{K4}\subseteq \mathsf L_h$.
If $\Phi \in W^{\rm c}$, then there exists a $\Sigma$-quasimodel $\mathfrak{Q}$ and a $\mathfrak{Q}$-morphism $\pi^\mathfrak{Q}$ for $[{\sf L}_h, {\sf GL}]^{\sf e}$ such that $\pi^\mathfrak{Q}(r^\mathfrak{Q}) = \Phi$.

\label{CompletenessK4GL}
The logic $[\sf{K4},\sf{GL}]^{\sf e}$ is sound and complete with respect to the following classes:
\begin{enumerate}
\item the class of expanding domain frames $(\sf{K4}\times \sf{GL})^{\sf e}$;
\item the class of embedding domain frames $(\sf{K4}\rtimes \sf{GL})^{\sf e}$;
\item the class of forward-confluent frames $\sf{K4}\rtimes \sf{GL}$.
\end{enumerate}

\label{thmYF}
Let $\Sigma\Subset\mathcal L_{hv}$, let $\mathsf L_h$, $\mathsf L_v$ be unimodal logics such that ${\sf L}_v \supseteq {\sf GL}$ and let $\mathcal M^{\rm c}$ be the canonical model for $[ \mathsf L_h, \mathsf L_v]^{\sf e}$. For any $\Sigma$-moment $\mathfrak m$ and any $\Phi \in W^{\rm c}$, the following are equivalent.
\begin{enumerate}
    \item\label{YFsim} $\mathfrak{m}\rightharpoonup \Phi$.
    \item\label{YFSimSat} $\Phi \in \left\llbracket{\rm Sim}(\mathfrak m)\right\rrbracket^{\rm c}$.
    \item\label{YFSimTruthLemma} ${\rm Sim}(\mathfrak{m}) \in \Phi$. 
\end{enumerate}

\label{lemExistsQuasi}
Let $\Sigma\Subset\mathcal L_{hv}$ and let $\mathcal{M}^{\rm c}$ be the canonical model of the expanding commutator $\sf [GL, GL]^{e}$. 
If $\Phi \in W^{\rm c}$, then there exists a finite $\Sigma$-quasimodel $\mathfrak{Q}$ and a $\mathfrak{Q}$-morphism $\pi^\mathfrak{Q}$ for $\sf [GL, GL]^{e}$ such that $\pi^\mathfrak{Q}(r^\mathfrak{Q}) = \Phi$.

\label{Completeness}
The logic $[\sf{GL},\sf{GL}]^{\sf e}$ is sound and complete with respect to the following classes:
\begin{enumerate}
\item the class of (finite) expanding domain frames $(\sf{GL}\times \sf{GL})^{\sf e}$;
\item the class of (finite) embedding domain frames $(\sf{GL}\rtimes \sf{GL})^{\sf e}$;
\item the class of (finite) forward-confluent frames $\sf{GL}\rtimes \sf{GL}$.
\end{enumerate}
